// --- INPUTS ---
// Get data from the AI Agent (passed through the If node)
const aiData = $('Check if Booking Ready').first().json;
// Get client data passed through from Step 2
const client = $('Format Context').first().json.client_data;

// --- HELPER FUNCTIONS ---
function normalizeRole(roleRaw) {
  const map = {
    'hca': 'healthcare_assistant',
    'care assistant': 'healthcare_assistant',
    'nurse': 'general_nurse',
    'rgn': 'general_nurse'
  };
  return map[roleRaw.toLowerCase()] || roleRaw.toLowerCase().replace(/ /g, '_');
}

// --- RATE LOOKUP ---
const roleKey = normalizeRole(aiData.role_raw || '');
const rates = client.contract_terms?.rates_by_role?.[roleKey];
const payRate = rates?.pay_rate || 0;
const chargeRate = rates?.charge_rate || 0;

// STRICT VALIDATION: Ensure both rates are valid
if (payRate <= 0 || chargeRate <= 0) {
    throw new Error(`Cannot book role '${roleKey}': Missing valid rates (Charge: ${chargeRate}, Pay: ${payRate}). Please check client contract terms.`);
}

// --- LOCATION VALIDATION ---
let workLocation = null;
if (aiData.location_raw) {
    const validLocations = client.internal_locations || [];
    // Simple case-insensitive match
    const match = validLocations.find(loc => loc.toLowerCase() === aiData.location_raw.toLowerCase());
    if (match) {
        workLocation = match;
    } else if (validLocations.length > 0) {
        workLocation = aiData.location_raw; // Fallback
    }
}

// --- AUTO-FILL DEFAULTS ---
let startTime = '08:00';
let endTime = '20:00';

if (aiData.shift_type === 'night') {
  startTime = client.night_shift_start || '20:00';
  endTime = client.night_shift_end || '08:00';
} else {
  startTime = client.day_shift_start || '08:00';
  endTime = client.day_shift_end || '20:00';
}

// Calculate Duration
const duration = 12; // Default to 12 hours

// Generate Output Items
const shifts = [];
for (let i = 0; i < (aiData.quantity || 1); i++) {
  shifts.push({
    client_id: client.client_id || client.id,
    agency_id: client.agency_id,
    date: aiData.date_expression, // In real app, use date-fns to parse 'tomorrow'
    start_time: startTime,
    end_time: endTime,
    role_required: roleKey,
    pay_rate: payRate,
    charge_rate: chargeRate,
    status: 'open',
    urgency: aiData.urgency,
    work_location_within_site: workLocation,
    notes: aiData.notes,
    created_by: 'AI Agent',
    created_date: new Date().toISOString(),
    shift_journey_log: JSON.stringify([{
      state: 'created',
      timestamp: new Date().toISOString(),
      method: 'ai_agent'
    }])
  });
}

return shifts;

// Get client data from previous node
const client = $('Get Client Data').first().json;

// 1. Filter Valid Roles (Must have charge_rate > 0)
const validRoles = [];
const rates = client.contract_terms?.rates_by_role || {};

for (const [roleKey, data] of Object.entries(rates)) {
  // STRICT VALIDATION: Both rates must be positive
  if (data.charge_rate > 0 && data.pay_rate > 0) {
    // Format: "Nurse (Charge: £20, Pay: £15)"
    validRoles.push(`${roleKey} (Charge: £${data.charge_rate}, Pay: £${data.pay_rate})`);
  }
}

// 2. Format Shift Times
const dayTimes = `${client.day_shift_start || '08:00'} - ${client.day_shift_end || '20:00'}`;
const nightTimes = `${client.night_shift_start || '20:00'} - ${client.night_shift_end || '08:00'}`;

// 3. Format Internal Locations
const locations = client.internal_locations || [];
const locationString = locations.length > 0 ? locations.join(', ') : 'None';

// 4. Construct Context String
// NOTE: Check if your node returns 'id' or 'client_id'
const clientId = client.client_id || client.id;

const contextString = `
CURRENT CLIENT CONTEXT:
- Name: ${client.name}
- ID: ${clientId}
- Agency ID: ${client.agency_id}
- Shift Times: Day (${dayTimes}), Night (${nightTimes})
- Valid Roles: ${validRoles.join(', ')}
- Available Locations: ${locationString}
`;

return { 
  contextString, 
  client_data: client // Pass full data through for later
};
